from math import sqrt, prod
from itertools import product

def is_lovely(n):
    for k in range(1, int(sqrt(n)) + 1):
        if n % k == 0:
            for factors in product(range(1, int(sqrt(n)) + 1), repeat=k):
                if prod(factors) == n:
                    if all(d**2 <= (n + d) for d in factors):
                        return True, factors
    return False, None

lovely_numbers = []
for n in range(1, 1000):  # Search within the first 1000 positive integers
    is_l, factors = is_lovely(n)
    if is_l:
        lovely_numbers.append((n,) + factors)
    if len(lovely_numbers) == 10:
        break

print(lovely_numbers)
```

